fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based and guaranteed 1 <= k < list.len()
    assert!(k >= 1 && k < list.len(), "k out of bounds");

    let idx = k - 1;  // convert to 0-based index
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // extend with all elements before idx
    new_list.extend_from_slice(&list[..idx]);
    // extend with all elements after idx
    new_list.extend_from_slice(&list[idx + 1..]);

    new_list
}

